SELECT COUNT(*) AS partidas_vencidas
FROM teams
WHERE team_id = 200 AND win = true;

SELECT COUNT(*) AS partidas_vencidas_azul
FROM teams
WHERE team_id = 100 AND win = true;

SELECT AVG(pg.game_length_s) AS duracao_media_segundos
FROM pro_games pg
WHERE pg.year = 2026;

SELECT COUNT(*) AS partidas
FROM matches
WHERE game_duration_s < 1500;

SELECT COUNT(DISTINCT game_id) AS partidas
FROM pro_games
WHERE game_length_s < 1500;

SELECT AVG(p.cs_total) AS cs_medio_top
FROM participants p
WHERE p.team_position = 'TOP';
